insert into public.questions (id, law, kind, difficulty, role_tag, question, options, answer_index, explanation, laws_edition) values
  ('L1-1dkjkge', 1, 'connaissance', 1, null, 'À quelle distance de la ligne de but se trouve le point de penalty ?', '["9,15 m","11 m","12 m","16,5 m"]'::jsonb, 1, 'Le point de réparation est situé à 11 m du milieu de la ligne de but, à égale distance des montants.', '2025/26'),
  ('L1-yatpku', 1, 'connaissance', 1, null, 'Quelles sont les dimensions intérieures d’un but ?', '["7,32 m × 2,44 m","7,50 m × 2,50 m","7,00 m × 2,40 m","7,32 m × 2,50 m"]'::jsonb, 0, 'La distance entre les montants est de 7,32 m et le bord inférieur de la barre transversale est à 2,44 m du sol.', '2025/26'),
  ('L1-13bzekx', 1, 'connaissance', 1, null, 'Quel est le rayon du cercle central ?', '["8 m","9,15 m","10 m","11 m"]'::jsonb, 1, 'Le cercle central a un rayon de 9,15 m, la distance réglementaire des adversaires au coup d’envoi.', '2025/26'),
  ('L2-1w3lp01', 2, 'connaissance', 1, null, 'Quelle doit être la circonférence du ballon réglementaire ?', '["64 à 66 cm","66 à 68 cm","68 à 70 cm","70 à 72 cm"]'::jsonb, 2, 'Le ballon mesure entre 68 et 70 cm de circonférence et pèse entre 410 et 450 g au début du match.', '2025/26'),
  ('L3-b05mmd', 3, 'connaissance', 1, null, 'Combien de joueurs minimum une équipe doit-elle compter pour que le match commence ou se poursuive ?', '["6","7","8","9"]'::jsonb, 1, 'Un match ne peut ni commencer ni se poursuivre si l’une des équipes compte moins de sept joueurs.', '2025/26'),
  ('L3-dygorz', 3, 'situation', 2, null, 'Pendant le jeu, un joueur échange sa place avec son gardien sans prévenir l’arbitre. Décision ?', '["Arrêt immédiat, coup franc indirect","Laisser jouer, avertir les deux joueurs au prochain arrêt de jeu","Avertir uniquement le gardien","Aucune sanction"]'::jsonb, 1, 'L’arbitre laisse le jeu se poursuivre et avertit les deux joueurs dès que le ballon est hors du jeu.', '2025/26'),
  ('L3-uiwyu8', 3, 'situation', 3, null, 'Un remplaçant entre sur le terrain sans autorisation et touche le ballon en plein jeu. Décision ?', '["Balle à terre, sans sanction","Coup franc indirect, sans sanction","Coup franc direct ou penalty, et avertissement","Exclusion du remplaçant"]'::jsonb, 2, 'Le remplaçant qui intervient sur le jeu est averti pour être entré sans autorisation. Le jeu reprend par un coup franc direct, ou un penalty, à l’endroit de l’intervention.', '2025/26'),
  ('L4-10zzf08', 4, 'situation', 1, null, 'Un attaquant perd accidentellement sa chaussure et marque dans la foulée. Décision ?', '["But refusé, coup franc indirect","But accordé","But refusé, balle à terre","But refusé et avertissement"]'::jsonb, 1, 'Un joueur qui perd accidentellement une chaussure et joue immédiatement le ballon ou marque ne commet pas d’infraction.', '2025/26'),
  ('L4-1f9ffzd', 4, 'connaissance', 1, null, 'Un joueur peut-il garder une bague si elle est recouverte de ruban adhésif ?', '["Oui, si l’arbitre l’accepte","Oui, toujours","Non, les bijoux sont interdits, même recouverts","Oui, pour les gardiens seulement"]'::jsonb, 2, 'Tous les bijoux sont interdits. Les recouvrir de ruban adhésif n’est pas autorisé.', '2025/26'),
  ('L5-7h1llp', 5, 'situation', 2, null, 'Le ballon touche l’arbitre et l’équipe qui n’avait pas la possession lance une attaque prometteuse. Décision ?', '["Le jeu continue","Coup franc indirect","Balle à terre","Le jeu continue, avantage"]'::jsonb, 2, 'Si le ballon touche un arbitre et qu’une équipe lance une attaque prometteuse, que la possession change ou que le ballon entre directement dans le but, le jeu est arrêté et repris par une balle à terre.', '2025/26'),
  ('L5-1ahovdi', 5, 'situation', 2, null, 'L’arbitre laisse l’avantage, mais l’action n’aboutit pas dans les secondes qui suivent. Décision ?', '["Le jeu continue, l’avantage a été donné","Sanctionner la faute initiale","Balle à terre","Coup franc indirect"]'::jsonb, 1, 'Si l’avantage escompté ne se concrétise pas immédiatement ou dans les secondes qui suivent, l’arbitre sanctionne la faute initiale.', '2025/26'),
  ('L5-11zzc29', 5, 'situation', 2, null, 'Après le coup de sifflet final, encore sur le terrain, un joueur insulte l’arbitre. Peut-il être exclu ?', '["Non, le match est terminé","Oui, l’arbitre peut montrer le carton rouge","Seulement par rapport écrit","Seulement s’il s’agit d’un capitaine"]'::jsonb, 1, 'L’arbitre peut montrer un carton de l’entrée sur le terrain jusqu’après la fin du match, y compris pendant la mi-temps, la prolongation et les tirs au but.', '2025/26'),
  ('L5-16ng9yf', 5, 'connaissance', 2, null, 'Laquelle de ces décisions peut être revue par l’assistance vidéo (VAR) ?', '["Un deuxième avertissement","Une exclusion directe","Un corner accordé à tort","Une rentrée de touche"]'::jsonb, 1, 'La VAR n’intervient que pour une erreur manifeste ou un incident grave manqué : but ou non, penalty ou non, exclusion directe et erreur d’identité.', '2025/26'),
  ('L6-1obgbqg', 6, 'connaissance', 1, null, 'Qui prend la décision finale sur un fait de jeu ?', '["L’arbitre assistant le plus proche","L’arbitre","Le quatrième arbitre","L’arbitre et ses assistants à la majorité"]'::jsonb, 1, 'Les autres arbitres assistent l’arbitre, mais la décision finale appartient toujours à l’arbitre.', '2025/26'),
  ('L6-2ztm85', 6, 'connaissance', 1, 'assistant', 'Où l’arbitre assistant doit-il se placer en règle générale ?', '["À hauteur du ballon","À hauteur de l’avant-dernier défenseur, ou du ballon s’il est plus près de la ligne de but","Au niveau de la ligne médiane","Près du poteau de coin"]'::jsonb, 1, 'L’assistant suit l’avant-dernier défenseur, ou le ballon s’il est plus près de la ligne de but que celui-ci : c’est la ligne qui sert à juger le hors-jeu.', '2025/26'),
  ('L6-18ih7ad', 6, 'connaissance', 2, 'assistant', 'Comment l’arbitre assistant signale-t-il un remplacement ?', '["Drapeau levé à la verticale d’une main","Drapeau tenu à deux mains au-dessus de la tête","Drapeau agité à l’horizontale","Drapeau pointé vers la ligne médiane"]'::jsonb, 1, 'Pour un remplacement, l’assistant se place à la ligne médiane et tient son drapeau à deux mains au-dessus de la tête.', '2025/26'),
  ('L6-oliohs', 6, 'situation', 2, 'assistant', 'Un défenseur commet une faute visible de l’assistant mais hors du champ de vision de l’arbitre. Que fait l’assistant ?', '["Rien, ce n’est pas son rôle","Il lève le drapeau, l’agite, puis indique la direction du coup franc","Il entre sur le terrain","Il prévient le quatrième arbitre"]'::jsonb, 1, 'L’assistant signale les fautes que l’arbitre n’a pas vues : drapeau levé et agité, puis direction du coup franc une fois le coup de sifflet donné.', '2025/26'),
  ('L7-zm6sma', 7, 'connaissance', 1, null, 'Quelle est la durée maximale de la pause de la mi-temps ?', '["10 minutes","15 minutes","20 minutes","Libre, selon l’arbitre"]'::jsonb, 1, 'Les joueurs ont droit à une pause qui ne doit pas dépasser 15 minutes. Le règlement de la compétition doit en préciser la durée.', '2025/26'),
  ('L7-ivzg8y', 7, 'situation', 2, null, 'Un penalty est accordé à la dernière seconde de la première période. Décision ?', '["La période est terminée, pas de penalty","La période est prolongée jusqu’à la fin du penalty","Le penalty est tiré au début de la seconde période","Le penalty devient un coup franc indirect"]'::jsonb, 1, 'Si un penalty doit être exécuté ou retiré, la période est prolongée jusqu’à ce que le penalty soit terminé.', '2025/26'),
  ('L8-pa52sq', 8, 'connaissance', 1, null, 'Un but peut-il être marqué directement sur le coup d’envoi ?', '["Non, jamais","Oui, contre l’équipe adverse uniquement","Oui, dans les deux buts","Seulement en prolongation"]'::jsonb, 1, 'Un but peut être marqué directement contre l’équipe adverse. Si le ballon entre directement dans le but du botteur, un corner est accordé à l’adversaire.', '2025/26'),
  ('L8-1dhdqgk', 8, 'connaissance', 2, null, 'Le jeu est arrêté alors que le ballon était dans la surface de réparation. À qui est donnée la balle à terre ?', '["Au capitaine de l’équipe qui défend","Au gardien de l’équipe qui défend","Au dernier joueur ayant touché le ballon","Aux deux équipes"]'::jsonb, 1, 'Dans la surface de réparation, la balle à terre est donnée au gardien qui défend. Ailleurs, au dernier joueur à avoir touché le ballon.', '2025/26'),
  ('L8-avsf9n', 8, 'connaissance', 2, null, 'À quelle distance les autres joueurs doivent-ils se tenir lors d’une balle à terre ?', '["2 m","4 m","9,15 m","Aucune distance"]'::jsonb, 1, 'Tous les autres joueurs, des deux équipes, doivent rester à au moins 4 m jusqu’à ce que le ballon soit en jeu.', '2025/26'),
  ('L9-bbwudr', 9, 'situation', 1, null, 'Le ballon roule sur la ligne de touche, une partie dépassant à l’extérieur du terrain. Décision ?', '["Rentrée de touche","Le ballon est toujours en jeu","Balle à terre","Selon l’assistant"]'::jsonb, 1, 'Le ballon n’est hors du jeu que lorsqu’il a entièrement franchi la ligne de but ou de touche, à terre ou en l’air.', '2025/26'),
  ('L9-1wrof6t', 9, 'situation', 1, null, 'Le ballon rebondit sur le poteau de coin et revient sur le terrain. Décision ?', '["Corner","Coup de pied de but","Le ballon reste en jeu","Balle à terre"]'::jsonb, 2, 'Le ballon qui rebondit sur un montant, la barre ou le poteau de coin et reste sur le terrain est toujours en jeu.', '2025/26'),
  ('L10-6qtc4o', 10, 'connaissance', 1, null, 'Quand un but est-il marqué ?', '["Dès que le ballon touche la ligne de but","Quand plus de la moitié du ballon a franchi la ligne","Quand le ballon a entièrement franchi la ligne entre les montants et sous la barre","Quand le ballon touche le filet"]'::jsonb, 2, 'Un but est marqué quand le ballon a entièrement franchi la ligne de but entre les montants et sous la barre transversale, sans infraction préalable.', '2025/26'),
  ('L10-fcefmh', 10, 'connaissance', 2, null, 'Un joueur exclu pendant la prolongation peut-il participer aux tirs au but ?', '["Oui","Non","Oui, s’il remplace le gardien","Seulement en cas d’égalité de nombre"]'::jsonb, 1, 'Seuls les joueurs sur le terrain à la fin du match, ou temporairement sortis, peuvent participer aux tirs au but. Un joueur exclu ne le peut pas.', '2025/26'),
  ('L11-irjxfv', 11, 'situation', 1, null, 'Un attaquant en position de hors-jeu reçoit le ballon directement sur une rentrée de touche. Décision ?', '["Coup franc indirect pour la défense","Le jeu continue","Rentrée de touche à refaire","Balle à terre"]'::jsonb, 1, 'Il n’y a pas d’infraction de hors-jeu si le joueur reçoit le ballon directement sur coup de pied de but, rentrée de touche ou corner.', '2025/26'),
  ('L11-1lm0wjr', 11, 'connaissance', 2, 'assistant', 'Quelles parties du corps sont prises en compte pour juger la position de hors-jeu ?', '["Tout le corps, bras compris","Uniquement les pieds","Les parties avec lesquelles un but peut être marqué, hors mains et bras","Le tronc uniquement"]'::jsonb, 2, 'On considère la tête, le corps et les pieds. Les mains et les bras ne comptent pas, gardiens compris. La limite haute du bras est le bas de l’aisselle.', '2025/26'),
  ('L11-ncp41h', 11, 'situation', 2, null, 'Un attaquant en position de hors-jeu ne touche pas le ballon et ne gêne aucun adversaire. Son coéquipier marque. Décision ?', '["But refusé, hors-jeu","But accordé","But refusé, coup franc direct","But accordé après consultation de l’assistant uniquement"]'::jsonb, 1, 'Être en position de hors-jeu n’est pas une infraction. Le joueur doit participer activement au jeu pour être sanctionné.', '2025/26'),
  ('L11-13pbmjr', 11, 'connaissance', 1, 'assistant', 'Un attaquant est exactement à la même hauteur que l’avant-dernier défenseur. Est-il en position de hors-jeu ?', '["Oui","Non","Seulement s’il est devant le ballon","Seulement dans la surface"]'::jsonb, 1, 'Un joueur à la même hauteur que l’avant-dernier adversaire, ou que les deux derniers, n’est pas en position de hors-jeu.', '2025/26'),
  ('L11-boelan', 11, 'connaissance', 1, null, 'Un joueur peut-il être en position de hors-jeu dans sa propre moitié de terrain ?', '["Oui","Non","Seulement en prolongation","Seulement si le gardien est sorti"]'::jsonb, 1, 'La position de hors-jeu n’existe que dans la moitié de terrain adverse, ligne médiane exclue pour la tête, le corps et les pieds.', '2025/26'),
  ('L11-9y5hh0', 11, 'situation', 3, 'assistant', 'Un attaquant en position de hors-jeu récupère le ballon après une parade délibérée d’un défenseur sur un tir. Décision ?', '["Le jeu continue, le défenseur a joué le ballon","Hors-jeu : un sauvetage ne remet pas l’attaquant en jeu","Balle à terre","Penalty"]'::jsonb, 1, 'Un sauvetage (arrêt ou tentative d’arrêter un ballon qui va au but) ne remet pas l’attaquant en jeu. Seul un jeu délibéré du ballon, hors sauvetage, le fait.', '2025/26'),
  ('L11-4ymofd', 11, 'connaissance', 1, null, 'Comment est sanctionnée une infraction de hors-jeu ?', '["Coup franc direct","Coup franc indirect à l’endroit de l’infraction","Coup de pied de but","Balle à terre"]'::jsonb, 1, 'L’infraction de hors-jeu est sanctionnée par un coup franc indirect là où elle a été commise, y compris dans la propre moitié du joueur.', '2025/26'),
  ('L12-zcjjhs', 12, 'situation', 2, null, 'Dans sa surface, un défenseur annihile une occasion de but manifeste en tentant réellement de jouer le ballon. Sanction ?', '["Penalty et exclusion","Penalty et avertissement","Penalty sans sanction disciplinaire","Coup franc indirect"]'::jsonb, 1, 'Dans la surface, si l’infraction est une tentative de jouer le ballon, la sanction est ramenée à un avertissement. Le penalty est accordé.', '2025/26'),
  ('L12-1j0cb4q', 12, 'situation', 2, null, 'Dans sa surface, un défenseur tire le maillot d’un attaquant et annihile une occasion de but manifeste. Sanction ?', '["Penalty et exclusion","Penalty et avertissement","Penalty uniquement","Coup franc direct à l’entrée de la surface"]'::jsonb, 0, 'Tenir, tirer ou pousser n’est pas une tentative de jouer le ballon : le joueur est exclu, même dans la surface de réparation.', '2025/26'),
  ('L12-dli4en', 12, 'situation', 2, null, 'Dans sa surface, un défenseur empêche un but par une main délibérée. Sanction ?', '["Penalty et avertissement","Penalty et exclusion","Penalty uniquement","Coup franc indirect"]'::jsonb, 1, 'Annihiler un but ou une occasion de but manifeste par une main délibérée entraîne l’exclusion, où que ce soit. Seul le gardien dans sa propre surface fait exception.', '2025/26'),
  ('L12-11vlfho', 12, 'situation', 1, null, 'Le gardien garde le ballon en main plus de 8 secondes. Décision ?', '["Coup franc indirect","Avertissement au gardien","Corner pour l’équipe adverse","Balle à terre"]'::jsonb, 2, 'Depuis l’édition 2025/26 des Lois du Jeu, un corner est accordé à l’adversaire. L’arbitre signale à la main les 5 dernières secondes.', '2025/26'),
  ('L12-1s14pgg', 12, 'situation', 2, null, 'Le ballon touche accidentellement la main d’un attaquant, puis un coéquipier marque. Décision ?', '["But refusé, coup franc direct","But accordé","But refusé, coup franc indirect","But refusé, balle à terre"]'::jsonb, 1, 'Seul le joueur qui marque directement, ou immédiatement après que le ballon a touché sa main même accidentellement, est sanctionné. Le but du coéquipier est valable.', '2025/26'),
  ('L12-1wu5m5h', 12, 'situation', 1, null, 'Un joueur enlève son maillot pour célébrer un but. Décision ?', '["Rien, le but est accordé","Avertissement","Exclusion","But refusé"]'::jsonb, 1, 'Enlever son maillot ou se couvrir la tête avec lors d’une célébration entraîne un avertissement. Le but reste valable.', '2025/26'),
  ('L12-chvx4r', 12, 'connaissance', 1, null, 'Le gardien prend à la main, dans sa surface, une passe délibérée du pied d’un coéquipier. Décision ?', '["Le jeu continue","Coup franc indirect","Coup franc direct","Penalty"]'::jsonb, 1, 'Le gardien ne peut pas toucher de la main un ballon que lui a délibérément passé du pied un coéquipier : coup franc indirect.', '2025/26'),
  ('L12-19inosv', 12, 'situation', 2, null, 'Un tacle met en danger l’intégrité physique de l’adversaire (excès d’engagement). Sanction ?', '["Coup franc direct sans carton","Coup franc direct et avertissement","Coup franc direct et exclusion","Coup franc indirect"]'::jsonb, 2, 'Imprudence : faute sans carton. Témérité : avertissement. Excès d’engagement : exclusion.', '2025/26'),
  ('L12-o9bpaa', 12, 'situation', 2, null, 'Hors de la surface, un défenseur arrête une attaque prometteuse par une faute. Sanction ?', '["Coup franc direct sans carton","Coup franc direct et avertissement","Coup franc direct et exclusion","Coup franc indirect"]'::jsonb, 1, 'Arrêter une attaque prometteuse par une faute est un comportement antisportif sanctionné d’un avertissement.', '2025/26'),
  ('L12-6pr2lz', 12, 'situation', 1, null, 'Un joueur crache sur un adversaire. Sanction ?', '["Avertissement","Exclusion et coup franc direct","Exclusion et coup franc indirect","Avertissement et coup franc indirect"]'::jsonb, 1, 'Cracher sur une personne est un motif d’exclusion. Sur un adversaire, en plein jeu, le jeu reprend par un coup franc direct.', '2025/26'),
  ('L12-m0sq8s', 12, 'situation', 1, null, 'Un attaquant se laisse tomber dans la surface pour simuler une faute. Décision ?', '["Penalty","Avertissement pour simulation","Exclusion","Rien"]'::jsonb, 1, 'Tenter de tromper l’arbitre en simulant une faute est un comportement antisportif : avertissement. Si le jeu a été arrêté, il reprend par un coup franc indirect.', '2025/26'),
  ('L13-dritn9', 13, 'situation', 2, null, 'Sur un coup franc, un attaquant se tient à moins d’1 m d’un mur de trois défenseurs au moment du tir. Décision ?', '["Coup franc à retirer","Coup franc indirect pour la défense","Avertissement à l’attaquant","Le jeu continue"]'::jsonb, 1, 'Quand un mur d’au moins trois défenseurs est formé, les attaquants doivent rester à au moins 1 m. Sinon : coup franc indirect pour l’équipe défendante.', '2025/26'),
  ('L13-hdptw1', 13, 'situation', 2, null, 'Un coup franc indirect entre directement dans le but adverse sans toucher personne. Décision ?', '["But accordé","Coup franc à retirer","Coup de pied de but","Corner"]'::jsonb, 2, 'Sur coup franc indirect, le ballon doit toucher un autre joueur avant d’entrer dans le but. Directement dans le but adverse : coup de pied de but.', '2025/26'),
  ('L13-1b4xle', 13, 'connaissance', 2, null, 'Coup franc pour la défense dans sa propre surface : quand le ballon est-il en jeu ?', '["Quand il sort de la surface","Dès qu’il est botté et bouge clairement","Quand un autre joueur l’a touché","Quand l’arbitre siffle"]'::jsonb, 1, 'Depuis 2019, le ballon est en jeu dès qu’il est botté et bouge clairement, même dans la surface. Les adversaires doivent en rester dehors.', '2025/26'),
  ('L14-1qr4qux', 14, 'situation', 2, null, 'Lors d’un penalty, le gardien quitte sa ligne trop tôt et arrête le tir. Décision ?', '["Le jeu continue","Le penalty est à retirer","Coup franc indirect pour l’attaque","Le penalty est accordé comme but"]'::jsonb, 1, 'Le penalty est à retirer. Le gardien reçoit une mise en garde à la première infraction, puis un avertissement en cas de récidive.', '2025/26'),
  ('L14-1l8uef3', 14, 'situation', 3, null, 'Le tireur feinte une fois sa course d’élan terminée, puis marque. Décision ?', '["But accordé","Penalty à retirer","Coup franc indirect pour la défense et avertissement","But accordé et avertissement"]'::jsonb, 2, 'Feinter une fois la course d’élan terminée est interdit : coup franc indirect pour la défense et avertissement au tireur. Feinter pendant la course est autorisé.', '2025/26'),
  ('L14-za3vfb', 14, 'situation', 2, null, 'Le penalty frappe le poteau et revient vers le tireur, qui marque. Décision ?', '["But accordé","Penalty à retirer","Coup franc indirect pour la défense","Coup de pied de but"]'::jsonb, 2, 'Le tireur ne peut pas toucher le ballon une deuxième fois avant qu’un autre joueur l’ait touché : coup franc indirect pour l’adversaire.', '2025/26'),
  ('L15-5h0bt3', 15, 'situation', 1, null, 'Un joueur effectue une rentrée de touche directement dans son propre but. Décision ?', '["But accordé","Rentrée de touche pour l’adversaire","Corner pour l’adversaire","Coup de pied de but"]'::jsonb, 2, 'On ne peut pas marquer directement sur rentrée de touche. Directement dans son propre but : corner pour l’adversaire.', '2025/26'),
  ('L15-1gmqsbv', 15, 'connaissance', 1, 'assistant', 'À quelle distance les adversaires doivent-ils se tenir lors d’une rentrée de touche ?', '["1 m","2 m","4 m","9,15 m"]'::jsonb, 1, 'Les adversaires doivent rester à au moins 2 m du point de la ligne de touche où la rentrée est effectuée.', '2025/26'),
  ('L15-1n0c8n5', 15, 'situation', 1, 'assistant', 'Le lanceur effectue sa rentrée de touche les deux pieds à l’intérieur du terrain. Décision ?', '["Le jeu continue","Rentrée de touche pour l’adversaire","Rentrée à refaire par le même joueur","Coup franc indirect"]'::jsonb, 1, 'Le lanceur doit avoir une partie de chaque pied sur la ligne de touche ou à l’extérieur. Sinon, la rentrée revient à l’adversaire.', '2025/26'),
  ('L16-8iei9l', 16, 'situation', 1, null, 'Sur un coup de pied de but, un défenseur reçoit le ballon dans sa propre surface. Décision ?', '["Coup de pied de but à retirer","Le jeu continue","Coup franc indirect pour l’adversaire","Balle à terre"]'::jsonb, 1, 'Le ballon est en jeu dès qu’il est botté et bouge clairement. Il peut être joué à l’intérieur de la surface de réparation.', '2025/26'),
  ('L16-1k98z14', 16, 'situation', 2, null, 'Sur un coup de pied de but, un attaquant resté dans la surface intercepte le ballon. Décision ?', '["Le jeu continue","Coup de pied de but à retirer","Coup franc indirect pour la défense","Avertissement à l’attaquant"]'::jsonb, 1, 'Un adversaire présent dans la surface au moment du coup de pied de but qui touche ou dispute le ballon avant un autre joueur : le coup de pied de but est à retirer.', '2025/26'),
  ('L17-1tahtum', 17, 'connaissance', 1, null, 'À quelle distance minimale de l’arc de coin les adversaires doivent-ils se tenir ?', '["5 m","7 m","9,15 m","11 m"]'::jsonb, 2, 'Les adversaires doivent rester à au moins 9,15 m de l’arc de coin jusqu’à ce que le ballon soit en jeu.', '2025/26'),
  ('L17-1u5ak2l', 17, 'situation', 2, null, 'Le tireur du corner touche le ballon une deuxième fois avant tout autre joueur, du pied. Décision ?', '["Le jeu continue","Corner à retirer","Coup franc indirect pour l’adversaire","Coup franc direct pour l’adversaire"]'::jsonb, 2, 'Le tireur ne peut pas rejouer le ballon avant qu’un autre joueur l’ait touché : coup franc indirect pour l’adversaire (coup franc direct si c’est une main).', '2025/26')
insert into public.lessons (law, title, points) values
  (1, 'Le terrain', '["Longueur de 90 à 120 m, largeur de 45 à 90 m (matchs internationaux : 100–110 m × 64–75 m).","Le rayon du cercle central et de l’arc de cercle de surface est de 9,15 m.","Point de penalty à 11 m ; surface de réparation à 16,5 m des montants.","Les lignes font partie des surfaces qu’elles délimitent."]'::jsonb),
  (2, 'Le ballon', '["Circonférence de 68 à 70 cm, poids de 410 à 450 g.","Si le ballon devient défectueux, le jeu est arrêté et repris par une balle à terre.","Un ballon supplémentaire ne peut entrer sur le terrain qu’avec l’accord de l’arbitre."]'::jsonb),
  (3, 'Les joueurs', '["Onze joueurs maximum, dont un gardien. Minimum sept pour commencer ou poursuivre.","Cinq remplacements maximum en compétition de haut niveau, en trois occasions plus la mi-temps.","Un remplaçant entre seulement après la sortie du joueur remplacé et avec l’autorisation de l’arbitre.","Échange joueur–gardien sans autorisation : laisser jouer, avertir les deux au prochain arrêt."]'::jsonb),
  (4, 'L’équipement des joueurs', '["Équipement obligatoire : maillot, short, chaussettes, protège-tibias, chaussures.","Les couleurs doivent distinguer les deux équipes, les arbitres et les gardiens.","Bijoux interdits, même recouverts de ruban adhésif.","Perdre une chaussure accidentellement puis jouer immédiatement n’est pas une infraction."]'::jsonb),
  (5, 'L’arbitre', '["L’arbitre peut revenir sur une décision tant que le jeu n’a pas repris.","Avantage : sanctionner la faute initiale s’il ne se concrétise pas dans les secondes qui suivent.","Ballon qui touche l’arbitre : balle à terre s’il y a changement de possession, attaque prometteuse ou but direct.","VAR : but ou non, penalty ou non, exclusion directe, erreur d’identité."]'::jsonb),
  (6, 'Les autres arbitres', '["Les arbitres assistants signalent les sorties, le hors-jeu et les fautes hors du champ de l’arbitre.","L’assistant se place à hauteur de l’avant-dernier défenseur, ou du ballon s’il est plus près de la ligne de but.","Le quatrième arbitre gère les remplacements et la zone technique.","La décision finale appartient toujours à l’arbitre."]'::jsonb),
  (7, 'La durée du match', '["Deux périodes de 45 minutes, sauf accord prévu par le règlement.","Pause de la mi-temps : 15 minutes maximum.","Le temps perdu (remplacements, blessures, gaspillage) est récupéré.","Une période est prolongée pour exécuter un penalty."]'::jsonb),
  (8, 'Coup d’envoi et reprise du jeu', '["Au coup d’envoi, le ballon doit clairement bouger.","Un but peut être marqué directement contre l’adversaire.","Balle à terre : au dernier joueur à avoir touché le ballon ; dans la surface, au gardien.","Les autres joueurs se tiennent à au moins 4 m de la balle à terre."]'::jsonb),
  (9, 'Ballon en jeu et hors du jeu', '["Le ballon est hors du jeu quand il a entièrement franchi une ligne.","Il reste en jeu s’il rebondit sur un montant, la barre, le poteau de coin ou un arbitre (sauf cas de balle à terre)."]'::jsonb),
  (10, 'L’issue d’un match', '["But : ballon entièrement au-delà de la ligne, entre les montants et sous la barre.","Tirs au but : alternés, cinq par équipe puis mort subite.","Seuls les joueurs sur le terrain à la fin du match peuvent tirer."]'::jsonb),
  (11, 'Le hors-jeu', '["Être en position de hors-jeu n’est pas une infraction.","Position : dans la moitié adverse, plus près de la ligne de but que le ballon et que l’avant-dernier adversaire.","Même hauteur que l’avant-dernier adversaire : pas de position de hors-jeu.","Mains et bras ne comptent pas pour juger la position.","Pas de hors-jeu sur coup de pied de but, rentrée de touche ou corner.","Un sauvetage du défenseur ne remet pas l’attaquant en jeu ; un jeu délibéré, oui."]'::jsonb),
  (12, 'Fautes et incorrections', '["Imprudence : faute sans carton. Témérité : avertissement. Excès d’engagement : exclusion.","Annihilation d’occasion dans la surface avec tentative de jouer le ballon : avertissement.","Main délibérée qui empêche un but : exclusion, sauf le gardien dans sa surface.","Gardien qui garde le ballon plus de 8 secondes : corner pour l’adversaire (2025/26).","Main d’un attaquant : sanctionnée seulement si lui-même marque directement ou immédiatement après."]'::jsonb),
  (13, 'Les coups francs', '["Adversaires à 9,15 m, sauf s’ils sont sur leur ligne de but entre les montants.","Mur d’au moins trois défenseurs : les attaquants restent à 1 m.","Coup franc indirect : bras levé jusqu’à ce que le ballon touche un autre joueur.","Coup franc indirect directement dans le but adverse : coup de pied de but."]'::jsonb),
  (14, 'Le penalty', '["Le gardien garde au moins une partie d’un pied sur la ligne ou au niveau de celle-ci.","Le ballon doit être botté vers l’avant.","Feinte autorisée pendant la course d’élan, interdite une fois la course terminée.","Infraction du gardien, ballon non entré : penalty à retirer."]'::jsonb),
  (15, 'La rentrée de touche', '["Les adversaires se tiennent à au moins 2 m du point de la rentrée.","Une partie de chaque pied sur la ligne ou à l’extérieur.","Pas de but direct ; dans son propre but, corner pour l’adversaire.","Le lanceur ne peut pas retoucher le ballon avant un autre joueur."]'::jsonb),
  (16, 'Le coup de pied de but', '["Le ballon est en jeu dès qu’il est botté et bouge clairement.","Les adversaires restent hors de la surface jusqu’à ce que le ballon soit en jeu.","Un but peut être marqué directement contre l’adversaire."]'::jsonb),
  (17, 'Le coup de pied de coin', '["Le ballon est placé dans l’arc de coin le plus proche de la sortie.","Adversaires à 9,15 m de l’arc jusqu’à ce que le ballon soit en jeu.","Un but peut être marqué directement contre l’adversaire.","Double touche du tireur : coup franc indirect pour l’adversaire."]'::jsonb)
