-- Fichier généré par tool/generate_seed.dart : ne pas modifier à la main.
-- 57 questions, 17 fiches.

on conflict (id) do update set
  law = excluded.law, kind = excluded.kind, difficulty = excluded.difficulty, role_tag = excluded.role_tag,
  question = excluded.question, options = excluded.options, answer_index = excluded.answer_index,
  explanation = excluded.explanation, laws_edition = excluded.laws_edition, active = true;

on conflict (law) do update set title = excluded.title, points = excluded.points;
